package com.bank.dedupe;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Collapses sorted settlement identifiers to distinct values in place.
public class DedupeService {
    private static final Logger log = Logger.getLogger(DedupeService.class.getName());

    // Precondition: sortedIds is sorted. Returns the count of unique values.
    // The first `returned` positions hold the distinct ids; the tail is stale.
    public int removeDuplicates(BigDecimal[] sortedIds) {
        if (sortedIds == null || sortedIds.length == 0) {
            return 0;
        }
        int slow = 0;   // last position of a unique value
        for (int fast = 1; fast < sortedIds.length; fast++) {
            // compareTo != 0 means numerically different (ignores scale).
            if (sortedIds[fast].compareTo(sortedIds[slow]) != 0) {
                slow++;                          // make room for a new unique
                sortedIds[slow] = sortedIds[fast];
            }
            // equal → duplicate → skip, fast moves on
        }
        int uniqueCount = slow + 1;
        log.info(() -> "Unique identifiers = " + uniqueCount
                + " out of " + sortedIds.length + " total");
        return uniqueCount;
    }
}
