package com.bank.dedupe;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: collapse a sorted settlement identifier list to distinct.
public class DedupeDemo {
    private static final Logger log = Logger.getLogger(DedupeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        DedupeService service = new DedupeService();

        // Sorted account identifiers from a settlement run (with repeats).
        // 2001 appears as 2001 and 2001.00 — numerically the same account.
        BigDecimal[] ids = {
            new BigDecimal("2001"), new BigDecimal("2001.00"),
            new BigDecimal("3001"), new BigDecimal("3001"),
            new BigDecimal("3001"), new BigDecimal("4005")
        };
        int unique = service.removeDuplicates(ids);

        StringBuilder distinct = new StringBuilder("[");
        for (int i = 0; i < unique; i++) {
            distinct.append(ids[i]);
            if (i < unique - 1) distinct.append(", ");
        }
        distinct.append("]");
        final String distinctStr = distinct.toString();
        log.info(() -> "Distinct accounts to notify (" + unique + "): " + distinctStr);
    }
}
